BEGIN READ ONLY; SET LOCAL statement_timeout='8000ms'; SET LOCAL lock_timeout='1000ms'; SET LOCAL TIME ZONE 'UTC';
SELECT jsonb_build_object('database',current_database(),'readonly',current_setting('transaction_read_only'),
'latest_versions',(SELECT jsonb_agg(version_id ORDER BY version_id) FROM(SELECT DISTINCT ON(version_id) version_id,is_applied FROM public.goose_db_version ORDER BY version_id,id DESC)v WHERE is_applied),
'rows90',(SELECT count(*) FROM public.goose_db_version WHERE version_id=90),
'rows91',(SELECT count(*) FROM public.goose_db_version WHERE version_id=91),
'complete_history_wire',(SELECT COALESCE(jsonb_agg(to_jsonb(v) ORDER BY id),'[]'::jsonb)::text FROM public.goose_db_version v),
'prior_history_wire',(SELECT COALESCE(jsonb_agg(to_jsonb(v) ORDER BY id),'[]'::jsonb)::text FROM public.goose_db_version v WHERE version_id NOT IN(90,91)),
'catalog90',jsonb_build_object(
 'tables',(SELECT COALESCE(jsonb_agg(jsonb_build_object('name',c.relname,'kind',c.relkind) ORDER BY c.relname),'[]'::jsonb) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN('capacity_guest_retirement_forwards','capacity_guest_retirement_forward_reads')),
 'functions',(SELECT COALESCE(jsonb_agg(jsonb_build_object('name',p.proname,'definition',pg_get_functiondef(p.oid)) ORDER BY p.proname),'[]'::jsonb) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN('guard_retirement_forward','guard_retirement_forward_read','guard_retirement_forward_delete_binding','guard_retirement_forward_terminal')),
 'triggers',(SELECT COALESCE(jsonb_agg(jsonb_build_object('name',t.tgname,'definition',pg_get_triggerdef(t.oid),'enabled',t.tgenabled,'deferred',t.tgdeferrable,'initially_deferred',t.tginitdeferred) ORDER BY t.tgname),'[]'::jsonb) FROM pg_trigger t WHERE NOT t.tgisinternal AND t.tgname IN('retirement_forward_chain','retirement_forward_read_chain','retirement_forward_delete_chain','retirement_forward_immutable','retirement_forward_read_immutable','retirement_forward_terminal')),
 'indexes',(SELECT COALESCE(jsonb_agg(jsonb_build_object('name',c.relname,'definition',pg_get_indexdef(i.indexrelid),'valid',i.indisvalid,'ready',i.indisready,'live',i.indislive) ORDER BY c.relname),'[]'::jsonb) FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid WHERE i.indrelid IN(SELECT c.oid FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN('capacity_guest_retirement_forwards','capacity_guest_retirement_forward_reads'))),
 'constraints',(SELECT COALESCE(jsonb_agg(jsonb_build_object('table',c.conrelid::regclass::text,'name',c.conname,'validated',c.convalidated,'definition',pg_get_constraintdef(c.oid)) ORDER BY c.conrelid,c.conname),'[]'::jsonb) FROM pg_constraint c WHERE c.conrelid IN(SELECT r.oid FROM pg_class r JOIN pg_namespace n ON n.oid=r.relnamespace WHERE n.nspname='public' AND r.relname IN('capacity_guest_retirement_forwards','capacity_guest_retirement_forward_reads')))),
 'catalog91',jsonb_build_object(
 'tables',(SELECT COALESCE(jsonb_agg(jsonb_build_object('name',c.relname,'kind',c.relkind) ORDER BY c.relname),'[]'::jsonb) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname='capacity_dispatch_http_maintenance_dispositions'),
 'columns',(SELECT COALESCE(jsonb_agg(jsonb_build_object('name',a.attname,'number',a.attnum,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid)) ORDER BY a.attnum),'[]'::jsonb) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=to_regclass('public.capacity_dispatch_http_maintenance_dispositions') AND a.attnum>0 AND NOT a.attisdropped),
 'functions',(SELECT COALESCE(jsonb_agg(jsonb_build_object('name',p.proname,'definition',pg_get_functiondef(p.oid)) ORDER BY p.proname),'[]'::jsonb) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN('http_maintenance_dispatch_result_valid','http_maintenance_dispatch_policy_projection','http_maintenance_dispatch_policy_continuous','http_maintenance_dispatch_members','http_maintenance_dispatch_effect_scan','http_maintenance_dispatch_effect_scan_tolerable','http_maintenance_dispatch_admission_valid','guard_http_maintenance_dispatch_disposition_insert','check_http_maintenance_dispatch_transition','guard_http_maintenance_dispatch_job_insert','immutable_http_maintenance_dispatch_disposition','guard_http_maintenance_dispatch_workflow','require_http_maintenance_dispatch_disposition_links')),
 'shared_dispatch_guard',(SELECT COALESCE(jsonb_agg(jsonb_build_object('name',p.proname,'definition',pg_get_functiondef(p.oid))),'[]'::jsonb) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname='guard_capacity_dispatch_job'),
 'triggers',(SELECT COALESCE(jsonb_agg(jsonb_build_object('name',t.tgname,'definition',pg_get_triggerdef(t.oid),'enabled',t.tgenabled,'deferred',t.tgdeferrable,'initially_deferred',t.tginitdeferred) ORDER BY t.tgname),'[]'::jsonb) FROM pg_trigger t WHERE NOT t.tgisinternal AND t.tgname IN('http_maintenance_dispatch_disposition_insert','http_maintenance_dispatch_disposition_immutable','http_maintenance_dispatch_job_insert','http_maintenance_dispatch_workflow_immutable','http_maintenance_dispatch_disposition_complete_links')),
 'indexes',(SELECT COALESCE(jsonb_agg(jsonb_build_object('name',c.relname,'definition',pg_get_indexdef(i.indexrelid),'valid',i.indisvalid,'ready',i.indisready,'live',i.indislive,'unique',i.indisunique) ORDER BY c.relname),'[]'::jsonb) FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid WHERE i.indrelid=to_regclass('public.capacity_dispatch_http_maintenance_dispositions')),
 'constraints',(SELECT COALESCE(jsonb_agg(jsonb_build_object('name',c.conname,'validated',c.convalidated,'definition',pg_get_constraintdef(c.oid)) ORDER BY c.conname),'[]'::jsonb) FROM pg_constraint c WHERE c.conrelid=to_regclass('public.capacity_dispatch_http_maintenance_dispositions')),
 'dispatch_constraints',(SELECT COALESCE(jsonb_agg(jsonb_build_object('name',c.conname,'validated',c.convalidated,'definition',pg_get_constraintdef(c.oid)) ORDER BY c.conname),'[]'::jsonb) FROM pg_constraint c WHERE c.conrelid='public.capacity_dispatch_jobs'::regclass AND c.conname IN('capacity_dispatch_jobs_state_v8_check','capacity_dispatch_jobs_lifecycle_v8_check','capacity_dispatch_jobs_state_v9_check','capacity_dispatch_jobs_lifecycle_v9_check')),
 'dispatch_columns',(SELECT COALESCE(jsonb_agg(jsonb_build_object('name',a.attname,'number',a.attnum,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid)) ORDER BY a.attnum),'[]'::jsonb) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid='public.capacity_dispatch_jobs'::regclass AND a.attnum>0 AND NOT a.attisdropped)),
'other_migrators_ddl',(SELECT count(*) FROM pg_stat_activity WHERE datname=current_database() AND pid<>pg_backend_pid() AND (application_name LIKE 'core-goose%' OR state='active' AND query~*'(^|[^a-z])(create|alter|drop|truncate|reindex|cluster|vacuum|do|call)([^a-z]|$)')),
'other_cic',(SELECT count(*) FROM pg_stat_progress_create_index WHERE datid=(SELECT oid FROM pg_database WHERE datname=current_database())),
'ddl_locks',(SELECT count(*) FROM pg_locks WHERE pid<>pg_backend_pid() AND relation IN(SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace) AND mode IN('ShareUpdateExclusiveLock','ShareLock','ShareRowExclusiveLock','ExclusiveLock','AccessExclusiveLock')));
COMMIT;